"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["72956"],{27114(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.ordem_com_codigo_desconhecido","status":422,"titulo":"A ordem cita um valor que o fato n\xe3o tem"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.ordem_com_codigo_desconhecido","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova ordem dos valores de um fato (`PUT /api/configuracao/admin/fatos-candidato/{id}/ordem-dos-valores`) com um c\xf3digo que n\xe3o pertence ao fato, ou com um c\xf3digo em branco. A ordem s\xf3 reorganiza os valores que o fato j\xe1 tem; o c\xf3digo de um valor n\xe3o muda e um valor novo n\xe3o entra por aqui. A corre\xe7\xe3o da ordem das op\xe7\xf5es de um fato \xe9 regra do UNI-REQ-0159; a lista completa e sem repeti\xe7\xe3o \xe9 a forma que a API exige para aplic\xe1-la de uma vez.","A recusa vem na lista `errors` da resposta, com `field` igual a `codigos`, e a mensagem diz o que corrigir. A ordem dos valores do fato n\xe3o \xe9 alterada. Se a lista tiver mais de um problema, cada um vem numa entrada pr\xf3pria da mesma resposta, e o mesmo c\xf3digo de erro pode aparecer em mais de uma entrada. Os espa\xe7os nas pontas de cada c\xf3digo s\xe3o desconsiderados, mas mai\xfasculas e min\xfasculas contam: `eja` n\xe3o \xe9 o mesmo valor que `EJA`."],"comoResolver":["A mensagem indica se a lista tem c\xf3digo desconhecido ou em branco, sem repetir o valor enviado. Troque cada c\xf3digo em branco ou desconhecido pelo c\xf3digo certo do valor, ou retire-o. Depois envie a lista completa, com todos os valores do fato, ativos e desativados, cada um uma vez. Para incluir uma op\xe7\xe3o nova, cadastre-a como valor do fato e reordene em seguida."],"ondeAparece":["Reordena\xe7\xe3o dos valores de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);